export function formatPrice(p) {
  if (p === null || p === undefined) return "-";
  if (typeof p === "string" && p.trim() === "") return "-";
  const n = Number(p);
  if (!Number.isFinite(n)) return "-";
  if (n < 0) return "var";

  // Use decimal string arithmetic to avoid floating point errors:
  // multiply by 1e6 by shifting the decimal point.
  let s = typeof p === "string" ? p.trim() : String(p);
  let m = /^\+?(\d*)\.?(\d*)(?:[eE]([+-]?\d+))?$/.exec(s);
  if (!m) {
    return "$" + (Math.round(n * 1e6 * 100 + 1e-6) / 100).toFixed(2);
  }
  let int = m[1] || "";
  let frac = m[2] || "";
  let exp = parseInt(m[3] || "0", 10) + 6;
  let digits = int + frac;
  let point = int.length + exp; // position of decimal point in digits
  if (point < 0) {
    digits = "0".repeat(-point) + digits;
    point = 0;
  }
  if (point > digits.length) digits = digits + "0".repeat(point - digits.length);
  let ip = digits.slice(0, point) || "0";
  let fp = digits.slice(point);
  fp = (fp + "00").slice(0, fp.length > 2 ? fp.length : 2);
  // round half up at 2 decimals
  let cents = BigInt(ip + fp.slice(0, 2));
  if (fp.length > 2 && fp.charCodeAt(2) >= 53) cents += 1n;
  let str = cents.toString().padStart(3, "0");
  return "$" + str.slice(0, -2) + "." + str.slice(-2);
}
