Notes on two edge cases:
- An id like `a-` directly before `>` is ambiguous. The `\s*->\s*` separator lets backtracking resolve it correctly.
- A label after `:` may be empty. In that case `label` is set to `undefined`.

```js
const VALID_KINDS = new Set(["flow", "call", "spawn", "handoff", "return", "data"]);

const EDGE_RE = /^\s*([A-Za-z0-9_.\-]+?)\s*->\s*([A-Za-z0-9_.\-]+)\s*(?:\[\s*([^\]]*?)\s*\])?\s*(?::([\s\S]*))?$/;

export function parseEdge(text) {
  if (typeof text !== "string") {
    return `Invalid edge: ${String(text)}`;
  }
  const m = EDGE_RE.exec(text);
  if (!m) {
    return `Invalid edge: "${text}" (expected "from -> to [kind]: label")`;
  }
  const [, from, to, rawKind, rawLabel] = m;
  const kind = rawKind === undefined ? "flow" : rawKind;
  if (!VALID_KINDS.has(kind)) {
    return `Invalid edge kind "${kind}" in "${text}" (valid: ${[...VALID_KINDS].join(", ")})`;
  }
  let label;
  if (rawLabel !== undefined) {
    const t = rawLabel.trim();
    label = t === "" ? undefined : t;
  }
  return { from, to, kind, label };
}
